// Susun data Monitoring Omzet Outlet dari sheet "Target Control".
// Input node: Baca Periode (MASTER TARGET A1:B3), Baca Target Unit (MASTER TARGET B33:D58), Baca Minggu 1..4 (MINGGUAN UNIT, kolom UNIT BISNIS|TARGET|REALISASI).
// Respon: {ok, generated_at, bulan:'YYYY-MM', periode:'November 2026', minggu, bobot_minggu:[4], outlet:[{nama, target_bulanan, target_per_minggu:[4], realisasi_per_minggu:[4 angka|null]}], gagal:[...], catatan:[...]}
// Aturan: realisasi kosong atau 0 = belum diisi (null), BUKAN omzet nol. Angka tidak pernah dikarang.
const BOBOT_DEFAULT = [0.27, 0.27, 0.23, 0.23];   // cadangan bila total target bulanan 0 / tidak terbaca
const BULAN = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
const t = v => (v == null ? '' : String(v).trim());
const key = v => t(v).toUpperCase().replace(/\s+/g, ' ');
// angka dari 58050000 / "Rp58.050.000" / "58,050,000" / "" → number | null
const num = v => {
  if (typeof v === 'number') return isFinite(v) ? v : null;
  let s = t(v).replace(/rp/i, '').replace(/\s/g, '');
  if (!s || s === '-') return null;
  if (/^-?\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) s = s.replace(/\./g, '').replace(',', '.');   // format Indonesia
  else s = s.replace(/,/g, '');
  const n = Number(s); return isFinite(n) ? n : null;
};
// Nama node bisa berakhiran angka di n8n (mis. "Baca Minggu 11" saat ditempel) → coba nama persis lalu +1..+5. null = tidak jalan.
const baca = node => {
  for (const n of [node, 1, 2, 3, 4, 5].map((x, i) => i ? node + x : node)) {
    try { return $(n).all().map(it => it.json); } catch (e) { /* coba nama berikutnya */ }
  }
  return null;
};
const gagal = [], catatan = [];
const rowsOf = node => { const r = baca(node); if (r === null || r.some(x => x && x.error)) { gagal.push(node); return []; } return r.filter(Boolean); };
const vals = r => Object.keys(r).filter(k => k !== 'row_number').map(k => r[k]);

// ---- periode (MASTER TARGET baris "PERIODE:") ----
let periodeDate = null;
const toDate = v => {
  if (typeof v === 'number' && v > 20000 && v < 80000) return new Date(Date.UTC(1899, 11, 30) + v * 864e5);   // serial number Sheets
  const s = t(v); let m = /^(\d{4})-(\d{1,2})-(\d{1,2})/.exec(s); if (m) return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})/.exec(s); if (m) return new Date(Date.UTC(+m[3], +m[2] - 1, +m[1]));      // dd/mm/yyyy (locale Indonesia)
  return null;
};
for (const r of rowsOf('Baca Periode')) {
  const v = vals(r);
  if (key(v[0]).startsWith('PERIODE')) periodeDate = toDate(v[1]);
  // bila rentang dimulai di baris PERIODE, judul kolomnya sendiri berisi tanggal
  Object.keys(r).forEach((k, i, ks) => { if (!periodeDate && key(k).startsWith('PERIODE') && ks[i + 1]) periodeDate = toDate(ks[i + 1]); });
}
if (!periodeDate) { const n = new Date(); periodeDate = new Date(Date.UTC(n.getFullYear(), n.getMonth(), 1)); catatan.push('PERIODE di MASTER TARGET tidak terbaca, memakai bulan berjalan'); }
const bulan = periodeDate.getUTCFullYear() + '-' + String(periodeDate.getUTCMonth() + 1).padStart(2, '0');
const periode = BULAN[periodeDate.getUTCMonth()] + ' ' + periodeDate.getUTCFullYear();

// ---- target bulanan per unit ----
const outlet = [], idx = {};
const ambil = nama => { const k = key(nama); if (!idx[k]) { idx[k] = { nama: t(nama), target_bulanan: null, target_per_minggu: [null, null, null, null], realisasi_per_minggu: [null, null, null, null] }; outlet.push(idx[k]); } return idx[k]; };
for (const r of rowsOf('Baca Target Unit')) {
  const nama = t(r['APA?'] ?? vals(r)[0]);
  if (!nama) continue;
  const tg = num(r['BERAPA RP'] ?? vals(r)[2]);
  ambil(nama).target_bulanan = tg;
}
// ---- target & realisasi mingguan ----
for (let w = 0; w < 4; w++) {
  for (const r of rowsOf('Baca Minggu ' + (w + 1))) {
    const nama = t(r['UNIT BISNIS']);
    if (!nama) continue;
    const o = ambil(nama), tg = num(r['TARGET']), re = num(r['REALISASI']);
    o.target_per_minggu[w] = tg;
    o.realisasi_per_minggu[w] = re && re !== 0 ? re : null;   // kosong/0 = belum diisi
  }
}
// outlet tanpa target bulanan di MASTER TARGET tapi ada target mingguan → jangan dikarang, catat saja
const hasil = outlet.filter(o => (o.target_bulanan || 0) > 0 || o.realisasi_per_minggu.some(v => v != null));
hasil.filter(o => !(o.target_bulanan > 0)).forEach(o => catatan.push('Target bulanan ' + o.nama + ' kosong di MASTER TARGET'));

// ---- bobot minggu = total target minggu ÷ total target bulanan ----
const totBulan = hasil.reduce((s, o) => s + (o.target_bulanan || 0), 0);
let bobot = [0, 1, 2, 3].map(w => { const s = hasil.reduce((a, o) => a + (o.target_per_minggu[w] || 0), 0); return totBulan > 0 ? Math.round(s / totBulan * 10000) / 10000 : null; });
if (bobot.some(b => b == null || b <= 0)) { bobot = BOBOT_DEFAULT.slice(); catatan.push('Bobot minggu dari sheet tidak terbaca, memakai default 27/27/23/23%'); }

// minggu pelaporan = minggu terakhir yang sudah ada realisasinya (0 = belum ada sama sekali)
let minggu = 0;
for (let w = 0; w < 4; w++) if (hasil.some(o => o.realisasi_per_minggu[w] != null)) minggu = w + 1;
if (!minggu) catatan.push('Realisasi per unit di MINGGUAN UNIT belum diisi');

return [{ json: { ok: true, generated_at: DateTime.now().setZone('Asia/Makassar').toISO(), sumber: 'Target Control · MINGGUAN UNIT', bulan, periode, minggu, bobot_minggu: bobot, outlet: hasil, gagal, catatan } }];
